INSERT INTO products (
  barcode, name, category, subcategory, bottle_size,
  price, stock_quantity, in_stock, markup_pct, updated_at
)
SELECT
  barcode, name, category, subcategory, bottle_size,
  price, stock_quantity, in_stock, 15, NOW()
FROM incoming
ON CONFLICT (barcode) WHERE barcode IS NOT NULL
DO UPDATE SET
  name           = EXCLUDED.name,
  category       = EXCLUDED.category,
  subcategory    = EXCLUDED.subcategory,
  bottle_size    = EXCLUDED.bottle_size,
  price          = EXCLUDED.price,
  stock_quantity = EXCLUDED.stock_quantity,
  in_stock       = EXCLUDED.in_stock,
  markup_pct     = EXCLUDED.markup_pct,
  updated_at     = NOW();
  -- image_url, description, country, alcohol_pct, rating, is_featured,
  -- is_trending, is_new_arrival, is_best_seller are PRESERVED on update.

-- Sanity: count what landed.
SELECT category, COUNT(*) AS n FROM products WHERE updated_at >= NOW() - INTERVAL '1 minute' GROUP BY category ORDER BY n DESC;

COMMIT;
